ficanceCategory": "regional"}, "_editLog": [{"timestamp": "2026-06-29T06:10:55Z", "editorId": "gpt-4o-mini·cloud·GH#28352150910", "field": "summary", "oldValue": "Christian orthodox-oriented jurisdiction in the czech republic and slovakia Headquartered in Prešov. Founded 1951.", "newValue": "The Orthodox Church of the Czech Lands and Slovakia, established in 1951, represents a significant branch of Eastern Orthodoxy, primarily serving the populations of the Czech Republic and Slovakia. Its headquarters in Prešov marks a geographical focal point for Orthodox Christians in Central Europe, a region historically shaped by the interplay of Catholicism and Protestantism. The church emerged in a context of post-World War II geopolitics, where religious identity became a means of asserting national autonomy in the face of Soviet influence and the legacy of Austro-Hungarian rule.

